const app=document.getElementById("app");
const drawer=document.getElementById("drawer"),backdrop=document.getElementById("backdrop"),modal=document.getElementById("modal"),modalContent=document.getElementById("modalContent"),toastEl=document.getElementById("toast");
const markets={spot:"السبوت",futures:"الفيوتشر",contracts:"العقود الأمريكية",us:"السوق الأمريكي",saudi:"السوق السعودي",forex:"الفوركس"};
const tfLabels={"15m":"15 د","30m":"30 د","1h":"ساعة","4h":"4 ساعات","1d":"يومي","1w":"أسبوعي","1M":"شهري"};
const THEME_KEY="smart_theme";
const tfs=["15m","30m","1h","4h","1d","1w","1M"];
const breadthRefs={"15m":"15m","30m":"30m","1h":"1h","4h":"4h","1d":"1d","1w":"1w","1M":"1M"};
const breadthRefLabel={"15m":"15د","30m":"30د","1h":"ساعة","4h":"4س","1d":"يومي","1w":"أسبوعي","1M":"شهري"};
function toast(x){toastEl.textContent=x;toastEl.classList.add("show");setTimeout(function(){toastEl.classList.remove("show")},2600)}
function openModal(x){modalContent.innerHTML=x;modal.classList.add("show");document.body.classList.add("modal-open")}
function closeModal(){modal.classList.remove("show");document.body.classList.remove("modal-open")}
function applyTheme(){const dark=localStorage.getItem(THEME_KEY)==="dark";document.body.classList.toggle("dark",dark);const b=document.getElementById("themeBtn");if(b){b.textContent=dark?"☀️":"🌙";b.setAttribute("aria-label",dark?"الوضع النهاري":"الوضع الليلي");b.setAttribute("title",dark?"الوضع النهاري":"الوضع الليلي")}}
function toggleTheme(){const dark=document.body.classList.toggle("dark");localStorage.setItem(THEME_KEY,dark?"dark":"light");applyTheme()}
async function loadSiteSettings(){
try{
 const controller=new AbortController(); const timer=setTimeout(function(){controller.abort()},4000);
 const r=await fetch("/api/settings",{credentials:"same-origin",signal:controller.signal}); clearTimeout(timer); if(!r.ok)return;
 const d=await r.json(),s=d.settings||{};
 window.__SITE_SETTINGS__=s;
 if(s.site_name){document.title=s.site_name}
 if(s.language==="en"){document.documentElement.lang="en";document.documentElement.dir="ltr"}
 else {document.documentElement.lang="ar";document.documentElement.dir="rtl"}
 if(s.accent)document.documentElement.style.setProperty("--accent",s.accent);
 if(s.accent2)document.documentElement.style.setProperty("--accent2",s.accent2);
 if(s.default_theme==="dark" && !localStorage.getItem(THEME_KEY)){localStorage.setItem(THEME_KEY,"dark")}
 if(s.default_theme==="light" && !localStorage.getItem(THEME_KEY)){localStorage.setItem(THEME_KEY,"light")}
 applyTheme();
}catch(e){}
}

const menuBtn=document.getElementById("menuBtn");
if(menuBtn)menuBtn.onclick=function(){drawer.classList.add("open");backdrop.classList.add("open");document.body.classList.add("drawer-open")};
const closeMenu=document.getElementById("closeMenu");
if(closeMenu)closeMenu.onclick=function(){drawer.classList.remove("open");backdrop.classList.remove("open");document.body.classList.remove("drawer-open")};
if(backdrop)backdrop.onclick=function(){drawer.classList.remove("open");backdrop.classList.remove("open");document.body.classList.remove("drawer-open")};
if(modal)modal.onclick=function(e){if(e.target===modal||e.target.hasAttribute("data-close"))closeModal()};
document.querySelectorAll(".drawer a").forEach(function(a){a.onclick=function(){drawer.classList.remove("open");backdrop.classList.remove("open");document.body.classList.remove("drawer-open")}});
document.addEventListener("click",function(e){const b=e.target.closest("#themeBtn");if(b){e.preventDefault();toggleTheme();}});
applyTheme();
const supportOpen=document.getElementById("supportOpen");
if(supportOpen)supportOpen.onclick=function(){drawer.classList.remove("open");backdrop.classList.remove("open");document.body.classList.remove("drawer-open");supportModal()};
const floatingSupport=document.getElementById("floatingSupport");
if(floatingSupport)floatingSupport.onclick=function(){supportModal()};

