async function saveSiteSettings(e){
 e.preventDefault();
 const fd=new FormData(e.target), q=new URLSearchParams(fd);
 const r=await fetch("/api/admin/settings?"+q.toString(),{method:"POST",credentials:"same-origin"});
 const d=await r.json().catch(function(){return {message:"تعذر الحفظ"}});
 toast(d.message||"تم الحفظ");
 if(r.ok){window.__SITE_SETTINGS__=d.settings||{};await loadSiteSettings()}
}
async function loadAdminSettings(){
 const r=await fetch("/api/admin/settings",{credentials:"same-origin"}); if(!r.ok)return;
 const d=await r.json(),s=d.settings||{};
 const form=document.querySelector('form[onsubmit="saveSiteSettings(event)"]'); if(!form)return;
 Object.keys(s).forEach(function(k){const el=form.elements[k];if(el)el.value=s[k]});
}
